def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find all row indices that are completely uniform (separator rows)
    sep_rows = []
    for r in range(rows):
        vals = set(grid[r])
        if len(vals) == 1:
            sep_rows.append(r)

    # Find all column indices that are completely uniform (separator cols)
    sep_cols = []
    for c in range(cols):
        vals = {grid[r][c] for r in range(rows)}
        if len(vals) == 1:
            sep_cols.append(c)

    # If no separators, return grid as is
    if not sep_rows and not sep_cols:
        return grid

    # Determine wall value from separator
    wall_val = grid[sep_rows[0]][0] if sep_rows else 0

    # Define background value (0 or 5 based on normal case)
    bg_val = 5 if wall_val == 0 else 0

    # Create output grid
    grid_out = [row[:] for row in grid]

    # Build row intervals between separator rows
    row_intervals = []
    sep_rows.sort()
    prev = 0
    for r in sep_rows:
        if r > prev:
            row_intervals.append(list(range(prev, r)))
        prev = r + 1
    if prev < rows:
        row_intervals.append(list(range(prev, rows)))

    # Build column intervals between separator cols
    col_intervals = []
    sep_cols.sort()
    prev = 0
    for c in sep_cols:
        if c > prev:
            col_intervals.append(list(range(prev, c)))
        prev = c + 1
    if prev < cols:
        col_intervals.append(list(range(prev, cols)))

    # Process each block
    for r_seg in row_intervals:
        for c_seg in col_intervals:
            # Find unique non-wall, non-background values (the marker(s))
            vals = set()
            for r in r_seg:
                for c in c_seg:
                    vals.add(grid[r][c])

            # Filter out wall and background
            candidates = [v for v in vals if v != wall_val and v != bg_val]
            if candidates:
                signal = candidates[0]
                color = signal + 5
                # Fill entire block with this color
                for r in r_seg:
                    for c in c_seg:
                        grid_out[r][c] = color

    return grid_out
